export type TtlCache<V> = {
  get(key: string): V | undefined;
  set(key: string, value: V): void;
  readonly size: number;
};

/** In-memory cache whose entries expire ttlMs after they are written. */
export function createTtlCache<V>(options: { ttlMs: number; now?: () => number }): TtlCache<V> {
  const now = options.now ?? Date.now;
  const entries = new Map<string, { value: V; expiresAt: number }>();

  return {
    get(key) {
      const entry = entries.get(key);
      if (!entry) return undefined;
      if (entry.expiresAt <= now()) {
        entries.delete(key);
        return undefined;
      }
      return entry.value;
    },
    set(key, value) {
      entries.set(key, { value, expiresAt: now() + options.ttlMs });
    },
    get size() {
      return entries.size;
    },
  };
}

/** Cities that differ only by case or surrounding spaces share one cache entry. */
export function cacheKey(city: string): string {
  return city.trim().toLowerCase();
}

import express from "express";
import { cacheKey, createTtlCache, type TtlCache } from "./cache";
import { WeatherResponse } from "./schema";
import type { Forecast, WeatherUpstream } from "./upstream";

export type CachedForecast = { forecast: Forecast; fetchedAt: string };

export function createApp(deps: { upstream: WeatherUpstream; cache?: TtlCache<CachedForecast> }) {
  const app = express();
  const cache = deps.cache ?? createTtlCache<CachedForecast>({ ttlMs: 60_000 });

  app.get("/api/weather/:city", async (req, res) => {
    const city = req.params.city.trim();
    if (!/^[\p{L} .'-]{1,64}$/u.test(city)) {
      res.status(400).json({ error: "Invalid city name" });
      return;
    }

    try {
      const key = cacheKey(city);
      let entry = cache.get(key);
      if (!entry) {
        entry = { forecast: await deps.upstream.fetchForecast(city), fetchedAt: new Date().toISOString() };
        cache.set(key, entry);
      }
      // Hits and misses go through the same schema, so cached responses cannot drift in shape.
      const body = WeatherResponse.parse({ city, ...entry.forecast, fetchedAt: entry.fetchedAt });
      res.json(body);
    } catch {
      res.status(502).json({ error: "Forecast provider unavailable" });
    }
  });

  return app;
}

import request from "supertest";
import { describe, expect, it } from "vitest";
import { createApp, type CachedForecast } from "../src/app";
import { createTtlCache } from "../src/cache";
import { WeatherResponse } from "../src/schema";
import { createMockUpstream } from "../src/upstream";

describe("weather caching", () => {
  it("serves repeated requests from the cache", async () => {
    const upstream = createMockUpstream({ latencyMs: 0 });
    const app = createApp({ upstream });

    await request(app).get("/api/weather/Berkeley");
    await request(app).get("/api/weather/berkeley");

    expect(upstream.calls).toBe(1);
  });

  it("returns cached and uncached responses with the same schema", async () => {
    const app = createApp({ upstream: createMockUpstream({ latencyMs: 0 }) });

    const miss = await request(app).get("/api/weather/Oakland");
    const hit = await request(app).get("/api/weather/Oakland");

    expect(WeatherResponse.safeParse(miss.body).success).toBe(true);
    expect(WeatherResponse.safeParse(hit.body).success).toBe(true);
    expect(Object.keys(hit.body).sort()).toEqual(Object.keys(miss.body).sort());
  });

  it("calls upstream again after the entry expires", async () => {
    let clock = 0;
    const upstream = createMockUpstream({ latencyMs: 0 });
    const cache = createTtlCache<CachedForecast>({ ttlMs: 1_000, now: () => clock });
    const app = createApp({ upstream, cache });

    await request(app).get("/api/weather/Alameda");
    clock = 1_500;
    await request(app).get("/api/weather/Alameda");

    expect(upstream.calls).toBe(2);
  });
});
